async function init(){const attempt=sessionDiagAttempt(CURRENT_NETWORK),generation=sessionGeneration;setWorkspaceVisible(false);renderNetworkLabel();bindNetworkControl();bindCatalogPreview();bindDevnetDemo();if(window.__KELVARA_HARNESS__?.contextUnavailable){document.body.dataset.appState=applicationState(false);renderSignedOutPrompt();return}walletAddress=null;walletSource=null;activeProvider=null;removeLegacyWalletState();updateWalletControl();if(!CURRENT_NETWORK){clearNetworkScopedState();sessionDiag(attempt,{stage:"redirect",ok:false,reason:"redirect-network"});location.replace("/?wallet_error=session");return}const consumed=await consumeHandoff(),restored=consumed?false:await restoreAppSession();if(!sessionContinuationCurrent(generation))return;let reconnected=false;if(!consumed&&!restored){let reconnect=null;try{reconnect=JSON.parse(sessionStorage.getItem(NETWORK_RECONNECT_KEY)||"null")}catch{}if(WALLET_SOURCES.includes(reconnect?.source)){sessionStorage.removeItem(NETWORK_RECONNECT_KEY);reconnected=true;try{await connectWallet(reconnect.source,{protectedStartup:true})}catch(error){sessionDiag(attempt,{stage:"redirect",network:CURRENT_NETWORK,ok:false,reason:"redirect-session",errorClass:sessionDiagErrorClass(error)});if(!sessionInvalidated)location.replace("/?wallet_error=session");return}}else{sessionDiag(attempt,{stage:"redirect",network:CURRENT_NETWORK,ok:false,reason:"redirect-session"});location.replace("/?wallet_error=session");return}}if(!sessionContinuationCurrent(generation))return;document.body.dataset.appState=applicationState(true);setWorkspaceVisible(true);const startupSession=await bootstrapAuthenticatedSession();if(!startupSession.ok){renderPortfolioUnavailable(startupSession.error);markServiceState("portfolio",false);return}prefetchWalletExposure();startConsoleLoading();const governanceHost=$("#governance-content"),independentTasks=[loadHealth()];if(location.hash==='#activity')independentTasks.push(loadActivity());if(location.hash==='#account')independentTasks.push(renderAccountDashboard());if(isDevnetDemo)independentTasks.push(initializeDevnetDemo());if(governanceHost&&governanceHost.id==="governance-content"&&typeof document.createElement==="function")independentTasks.push(loadGovernance());let inspection;try{inspection=await inspect()}catch(error){if(sessionContinuationCurrent(generation)&&!["stale_inspection","wallet_session_ended","network_switch_pending"].includes(error?.message))portfolioLoadFailed();throw error}finishPortfolioLoading(inspection);if(!sessionContinuationCurrent(generation)||inspection?.portfolio?.walletId!==walletAddress||CURRENT_NETWORK!==RESOLVED_CONTEXT.network)return;try{await loadProtection(inspection.portfolio)}finally{paneLoaded("exitrail")}await Promise.allSettled(independentTasks);if(sessionContinuationCurrent(generation)&&governanceHost&&governanceHost.id==="governance-content"&&typeof document.createElement==="function"){if(typeof document!=="undefined"){governancePoller=createDomPoller({intervalMs:GOVERNANCE_POLL_MS,fetchValue:()=>loadGovernance(),render:()=>{},renderUnavailable:()=>{},paused:()=>document.visibilityState==="hidden"}).start();safeguardsPoller=createDomPoller({intervalMs:3000,fetchValue:()=>loadGroupedSafeguards(walletAddress),render:()=>{},renderUnavailable:()=>{}}).start();document.addEventListener("visibilitychange",()=>{if(document.visibilityState!=="hidden"&&sessionContinuationCurrent(sessionGeneration)){governancePoller?.poll();safeguardsPoller?.poll()}})}}}
